action.command:
python3 -c "$(cat <<'PY'
import json, sys
try:
    data = json.load(sys.stdin)
except Exception:
    raise SystemExit(0)
def paths(o, key=''):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from paths(v, k)
    elif isinstance(o, list):
        for v in o:
            yield from paths(v, key)
    elif isinstance(o, str) and any(s in key.lower() for s in ('path', 'file')):
        yield o
if any(r.strip().lower().endswith('.sh') for r in paths(data)):
    print('Blocked: this project does not use .sh files. Run commands directly from Kiro (sam, aws, npm, python3).', file=sys.stderr)
    raise SystemExit(2)
PY
)"
